arguments.command:
cd /tmp/sv-7e4ec9100ae641f5b146ff4b62413c6d && \
# Find symbols containing the addresses from the backtrace
# Frames: 0x222098, 0x222234, 0x19bac0, 0x19bc14
for addr in 0x222098 0x222234 0x19bac0 0x19bc14; do
  echo "=== $addr ==="
  readelf -W --dyn-syms libmonosgen.so | awk -v a="$addr" '
    BEGIN { addr = strtonum(a); best_name=""; best_addr=0; best_size=0 }
    /FUNC/ {
      sym_addr = strtonum("0x"$2);
      sym_size = strtonum($3);
      if (sym_addr <= addr && sym_addr > best_addr) {
        best_addr = sym_addr; best_name = $NF; best_size = sym_size
      }
    }
    END { if (best_name != "") printf "%s+0x%x\n", best_name, addr-best_addr; else print "unknown" }
  '
done

