arguments.command:
cd /tmp/sv-7e4ec9100ae641f5b146ff4b62413c6d && \
# Get all function symbols sorted by address, then find closest for each target
readelf -W --dyn-syms libmonosgen.so | awk '$4=="FUNC" && $2!="0000000000000000" {print "0x"$2, $3, $NF}' | sort -k1,1 > /tmp/syms.txt
for addr in 0x222098 0x222234 0x19bac0 0x19bc14; do
  echo "=== $addr ==="
  awk -v a="$addr" '
    BEGIN { addr = strtonum(a); best_name=""; best_addr=0 }
    {
      sym_addr = strtonum($1);
      sym_size = strtonum($2);
      if (sym_addr <= addr && sym_addr + sym_size > addr) {
        printf "%s+0x%x (size=0x%x)\n", $3, addr-sym_addr, sym_size; found=1; exit
      }
      if (sym_addr <= addr && sym_addr > best_addr) {
        best_addr = sym_addr; best_name = $3; best_size = sym_size
      }
    }
    END { if (!found) printf "(nearest) %s+0x%x (size=0x%x)\n", best_name, addr-best_addr, best_size }
  ' found=0 /tmp/syms.txt
done

